60	fn transform_file_name(input: &str) -> String {
61	    let mut result = biome_string_case::Case::Snake.convert(input);
62	
63	    let is_keyword = matches!(
64	        result.as_str(),
65	        "await"
66	            | "break"
67	            | "try"
68	            | "do"
69	            | "for"
70	            | "return"
71	            | "if"
72	            | "while"
73	            | "in"
74	            | "async"
75	            | "else"
76	            | "as"
77	            | "abstract"
78	            | "enum"
79	            | "static"
80	            | "yield"
81	            | "type"
82	            | "super"
83	            | "typeof"
84	            | "const"
85	    );
86	
87	    if is_keyword {
88	        result.push('_');
89	    } else if matches!(result.bytes().next(), Some(b'0'..=b'9')) {
90	        result.insert(0, '_');
