119	    fn print(self, output: &mut proc_macro2::TokenStream) {
120	        for (name, module) in self.modules {
121	            let name = syn::Ident::new(&name, Span::call_site());
122	
123	            let mut stream = proc_macro2::TokenStream::new();
124	            module.print(&mut stream);
125	            output.extend(quote! {
126	                mod #name { #stream }
127	            });
128	        }
129	
